// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(1000, "Test", "TST"); }
    function testFuzz_property(uint256 burnAmount) public {
        vm.assume(burnAmount > 0);
        vm.assume(burnAmount <= c.balanceOf(address(this)));
        uint256 initialTotalSupply = c.totalSupply();
        uint256 initialOwnerBalance = c.balanceOf(address(this));
        c.burn(burnAmount);
        uint256 finalTotalSupply = c.totalSupply();
        uint256 finalOwnerBalance = c.balanceOf(address(this));
        uint256 balanceDecrease = initialOwnerBalance - finalOwnerBalance;
        assertTrue(initialTotalSupply - finalTotalSupply == balanceDecrease);
    }
}
